import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const d=JSON.parse(`{"title":"Page 11 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"11","title":"Page 11 | Home","prev":"/page/10/","next":"/page/12/","posts":[{"title":"ELK收集Docker项目的日志","url":"/posts/2021-06-14-elk-docker/","date":"2021-06-14 11:21","tags":["ELK docker"],"html":"<p>现在主流的项目部署都是采用 docker 部署了，一般项目使用 <code>STDOUT</code> 输出的日志都被 docker 来收集和保存。我们需要使用著名的 <a href=\\"https://www.elastic.co/what-is/elk-stack\\" target=\\"_blank\\" rel=\\"noreferrer\\">ELK</a> 来分析日志，所以如何部署 ELK 并且把 docker 的日志转发给 ELK 呢？ 这就是本篇文章我们需要解决的问题。</p>\\n<h2 id=\\"搭建-elk\\" tabindex=\\"-1\\">搭建 ELK <a class=\\"header-anchor\\" href=\\"#搭建-elk\\" aria-label=\\"Permalink to &quot;搭建 ELK&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>既然我们使用 docker 进行部署，那我们当然也要使用 docker 部署 ELK。<a href=\\"https://github.com/deviantony/docker-elk\\" target=\\"_blank\\" rel=\\"noreferrer\\">docker-elk</a> 是一个配置好的项目，我们可以基于这个项目迅速搭建起一个 ELK 项目。说实话， ELK 项目非常消耗内存，所以至少保证机器有 4GB 内存，否则可能会宕机。搭建好 ELK 之后，记得按照教程重新设置密码。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$ docker-compose exec -T elasticsearch bin/elasticsearch-setup-passwords auto --batch</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>初始化密码之后，并修改 <code>kibana</code> 和 <code>logstash</code> 的配置文件更新密码。最后再重启这两个服务：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$ docker-compose restart kibana logstash</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"使用-gelf-收集日志\\" tabindex=\\"-1\\">使用 GELF 收集日志 <a class=\\"header-anchor\\" href=\\"#使用-gelf-收集日志\\" aria-label=\\"Permalink to &quot;使用 GELF 收集日志&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://docs.graylog.org/en/4.0/pages/gelf.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">GELF</a> 是一个经典的日志格式并且 docker 原生支持这个格式，首先我们需要配置 <code>logstash</code> 采取这个格式来收集日志。</p>\\n<p>修改 <code>logstash/pipeline/logstash.conf</code> 文件的 input 部分：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>input {</span></span>\\n<span class=\\"line\\"><span>\\tbeats {</span></span>\\n<span class=\\"line\\"><span>\\t\\tport => 5044</span></span>\\n<span class=\\"line\\"><span>\\t}</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>\\tgelf {</span></span>\\n<span class=\\"line\\"><span>\\t\\tport => 5000</span></span>\\n<span class=\\"line\\"><span>\\t}</span></span>\\n<span class=\\"line\\"><span>}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>这样收集 <code>gelf</code> 的端口就是 <code>5000</code> 默认使用 UDP 格式。修改配置之后别忘了重启 <code>logstash</code>。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$ docker-compose restart logstash</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来实际项目要把日志转发到 <code>ELK</code> 上，如果我们使用 <code>docker-compose.yml</code> 需要在当前的 <code>service</code> 上添加 <code>logging</code> 相关的配置：</p>\\n<div class=\\"language-yaml line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">yaml</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#22863A\\">logging</span><span style=\\"color:#24292E\\">:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">  driver</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">gelf</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">  options</span><span style=\\"color:#24292E\\">:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">    gelf-address</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">'udp://0.0.0.0:5000'</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>如果你的 ELK 和 实际项目并不是在同一台主机上，记得修改 <code>0.0.0.0</code> 成相应的主机名或 IP 地址。这样配置之后就可以在 <code>kibana</code> 上查看收集到的日志了。\\n不过要记得配置 <code>Index patterns</code> 然后在 <code>Discover</code> 界面上就能看到日志记录了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>ELK 收集 docker 日志并不是很复杂，但是摸索的时候很难调试，例如 ELK 配置了 <code>gelf</code> 方法收集日志，但却找不到好的方法来测试这个接口是否正常。\\n我只是通过 <code>nmap</code> 命令来检测 5000 端口是否开放，并不知道是否正常运行。</p>\\n<p>扫描当前主机的 UDP 端口：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>nmap -sU 0.0.0.0</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>启动项目的 docker 的时候还出现了警告信息 <code>warning: no logs are available with the 'gelf' log driver</code> 为了这个问题我查了半天，但发现\\n这个信息即使出现了也可以正常收集。浪费了不少时间。最终的解决方案总是很简单，但查找的过程中难免绕弯路。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://ibm-cloud-architecture.github.io/b2m-nodejs/logging/\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ibm-cloud-architecture.github.io/b2m-nodejs/logging/</a></p>\\n<p><a href=\\"https://www.nginx.com/blog/using-free-ssltls-certificates-from-lets-encrypt-with-nginx/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using Free Let’s Encrypt SSL/TLS Certificates with NGINX</a></p>\\n"},{"title":"Django使用CKEditor的相关经验","url":"/posts/2021-05-19-django-ckeditor-s3/","date":"2021-05-19 22:06","tags":["django"],"html":"<p>最近在使用 Django 进行后台管理系统的开发，其中有需求要使用所见即所得的富文本编辑器来让用户上传图片和文字并排版。这里我们选择了<a href=\\"https://github.com/django-ckeditor/django-ckeditor\\" target=\\"_blank\\" rel=\\"noreferrer\\">CKEditor</a>，原因很简单，因为这个第三方库提供了很好的 AWS S3 的支持，而我们目前也确实把静态资源例如图片放在 S3 上。</p>\\n<h2 id=\\"配置-aws-s3\\" tabindex=\\"-1\\">配置 AWS S3 <a class=\\"header-anchor\\" href=\\"#配置-aws-s3\\" aria-label=\\"Permalink to &quot;配置 AWS S3&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们一般使用<a href=\\"https://github.com/jschneier/django-storages\\" target=\\"_blank\\" rel=\\"noreferrer\\">django-storages</a>这个库来集成 AWS S3,\\n首先需要在设置里面配置 AWS 的 <code>AWS_ACCESS_KEY_ID</code>， <code>AWS_SECRET_ACCESS_KEY</code> 和 <code>AWS_S3_REGION_NAME</code>。</p>\\n<p>然后自定义一个 Storage class 方便配置，代码如下：</p>\\n<div class=\\"language-python line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">python</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">class</span><span style=\\"color:#6F42C1\\"> MaterialStorage</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#6F42C1\\">S3Boto3Storage</span><span style=\\"color:#24292E\\">):</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    bucket_name </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'material-bucket'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    default_acl </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'private'</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>默认都是私有桶，避免用户拿到图片的 URL 就可以分享给别人。S3 默认开启 <code>AWS_QUERYSTRING_AUTH</code>， 访问资源的格式类似下面这种带有查询参数：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>https://s3.amazonaws.com/photos/puppy.jpg?AWSAccessKeyId=AKIAIOSFODNN7EXAMPLE&#x26;Signature=NpgCjnDzrM%2BWFzoENXmpNDUsSn8%3D&#x26;Expires=1175139620</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>默认的查询参数认证有效期是一个小时，也就意味着这个链接最多一个小时有效，而且认证参数最大只能设置一周有效。可以有效避免链接泄漏导致的资源泄漏风险。</p>\\n<h2 id=\\"配置项目导入-ckeditor\\" tabindex=\\"-1\\">配置项目导入 CKEditor <a class=\\"header-anchor\\" href=\\"#配置项目导入-ckeditor\\" aria-label=\\"Permalink to &quot;配置项目导入 CKEditor&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>按照官方指导可以很顺利的导入 CKEditor：</p>\\n<div class=\\"language-python line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">python</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#24292E\\"> django.db </span><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> models</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#24292E\\"> ckeditor.fields </span><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> RichTextUploadingField</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">class</span><span style=\\"color:#6F42C1\\"> Post</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#6F42C1\\">models</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">Model</span><span style=\\"color:#24292E\\">):</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    content </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> RichTextUploadingField()</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><h2 id=\\"ckeditor-配置-s3\\" tabindex=\\"-1\\">CKEditor 配置 S3 <a class=\\"header-anchor\\" href=\\"#ckeditor-配置-s3\\" aria-label=\\"Permalink to &quot;CKEditor 配置 S3&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>官方教程上说明必须关掉<a href=\\"https://github.com/django-ckeditor/django-ckeditor#using-s3\\" target=\\"_blank\\" rel=\\"noreferrer\\">AWS_QUERYSTRING_AUTH</a>才能正常使用。但是关掉之后就意味着任何人只要获得资源的链接就可以访问，这是很危险的。所以我们如何保证开启认证参数的同时又能正常使用编辑器呢？这个才是本文的重点。</p>\\n<p>在开启认证参数的时候，编辑器保存的是当时上传照片时候的认证参数，也就意味着一个小时之后再访问的时候，就没法正常显示图片。如何保证页面载入编辑器的时候，保证图片正常显示呢？</p>\\n<p>我的思路是在页面载入的时候读取编辑器里面的内容，采用正则表达式匹配存储在 AWS 上的图片，然后更新图片相关的认证信息。</p>\\n<h2 id=\\"数据库读入时自动更新认证信息\\" tabindex=\\"-1\\">数据库读入时自动更新认证信息 <a class=\\"header-anchor\\" href=\\"#数据库读入时自动更新认证信息\\" aria-label=\\"Permalink to &quot;数据库读入时自动更新认证信息&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>查看 Django 文档的时候发现，我们可以自定义一个 field，然后使用一个 hook 函数 <a href=\\"https://docs.djangoproject.com/en/3.2/ref/models/fields/#django.db.models.Field.from_db_value\\" target=\\"_blank\\" rel=\\"noreferrer\\">from_db_value</a>。在数据读入的时候进行相关操作，例如把存入的 JSON 字符串转换成 JSON 对象。通过这个方法，我们可以对数据进行加工，更新图片的认证信息。</p>\\n<div class=\\"language-python line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">python</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">class</span><span style=\\"color:#6F42C1\\"> CKEditorField</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#6F42C1\\">RichTextUploadingField</span><span style=\\"color:#24292E\\">):</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    def</span><span style=\\"color:#6F42C1\\"> from_db_value</span><span style=\\"color:#24292E\\">(self, value, expression, connection):</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> value:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#24292E\\"> update_image(value)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        else</span><span style=\\"color:#24292E\\">:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#24292E\\"> value</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br></div></div><p>我们自定义了一个 <code>CKEditorField</code> 字段，从数据库读出的时候进行图片认证信息的更新。<code>update_image</code> 函数的实现如下：</p>\\n<div class=\\"language-python line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">python</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">def</span><span style=\\"color:#6F42C1\\"> update_image</span><span style=\\"color:#24292E\\">(content):</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    storage </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> MaterialStorage()</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    s3_regex </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> re.compile(</span><span style=\\"color:#D73A49\\">r</span><span style=\\"color:#032F62\\">'\\"</span><span style=\\"color:#005CC5\\">(</span><span style=\\"color:#032F62\\">https:</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/\\\\/</span><span style=\\"color:#032F62\\">amazonaws</span><span style=\\"color:#005CC5\\">.</span><span style=\\"color:#032F62\\">com</span><span style=\\"color:#005CC5\\">\\\\S</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\">)</span><span style=\\"color:#032F62\\">\\"'</span><span style=\\"color:#24292E\\">, re.</span><span style=\\"color:#005CC5\\">MULTILINE</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    links </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> s3_regex.findall(content)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    for</span><span style=\\"color:#24292E\\"> link </span><span style=\\"color:#D73A49\\">in</span><span style=\\"color:#24292E\\"> links:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        match </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> re.search(</span><span style=\\"color:#D73A49\\">r</span><span style=\\"color:#032F62\\">'</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#032F62\\">upload</span><span style=\\"color:#005CC5\\">\\\\S</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\">.(</span><span style=\\"color:#032F62\\">png</span><span style=\\"color:#D73A49\\">|</span><span style=\\"color:#032F62\\">jpe</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">g</span><span style=\\"color:#005CC5\\">)</span><span style=\\"color:#032F62\\">'</span><span style=\\"color:#24292E\\">, link)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> match:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            path </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> match.group()</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            if</span><span style=\\"color:#24292E\\"> storage.exists(path):</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                content </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> content.replace(link, storage.url(path))</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> content</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>简单的解释一下代码功能，首先匹配 AWS 链接，然后匹配链接中的图片路径，知道图片路径之后。再使用 <code>storage</code> 对象查找是否存在，如果存在的话，获取这个资源的 URL。这时候新的 URL 就带有新的认证信息。通过这种方式，我们就能保证每次页面显示编辑器的时候，里面的图片都可以正常显示出来。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>知道答案之后，当然觉得这么做很简单。但是探索出这个答案却非常花时间，首先要明确解决问题的思路，然后顺着这个思路去想出可能的解决方案。最后，问题迎刃而解。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://docs.aws.amazon.com/AmazonS3/latest/API/sigv4-query-string-auth.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Authenticating Requests: Using Query Parameters</a></p>\\n<p><a href=\\"https://docs.djangoproject.com/en/3.2/ref/files/storage/\\" target=\\"_blank\\" rel=\\"noreferrer\\">File storage API</a></p>\\n"},{"title":"使用Service Worker的 Web Push 功能","url":"/posts/2021-04-25-service-worker-push/","date":"2021-04-25 12:27","tags":["web"],"html":"<p>现代的 Android 应用和 iOS 应用都有相应的推送系统，可以给用户推送消息。即使用户没有打开这个应用，也同样可以收到消息。当然，网页既然要向手机应用靠拢的话，那推送功能也是必不可少。\\n今天我们就来介绍一下，网页如何实现类似的推送功能。</p>\\n<h2 id=\\"基于-service-worker-的推送功能\\" tabindex=\\"-1\\">基于 Service Worker 的推送功能 <a class=\\"header-anchor\\" href=\\"#基于-service-worker-的推送功能\\" aria-label=\\"Permalink to &quot;基于 Service Worker 的推送功能&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Service Worker 提供了两种推送服务，一种是基于 Firebase Cloud Messaging 的推送功能，一种是基于 VAPID 的推送功能。第一种已经过时了，所以本文只介绍第二种。</p>\\n<h3 id=\\"create-a-public-private-key-pair\\" tabindex=\\"-1\\">Create a public/private key pair <a class=\\"header-anchor\\" href=\\"#create-a-public-private-key-pair\\" aria-label=\\"Permalink to &quot;Create a public/private key pair&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>首先，我们需要创建公钥和私钥，类似与 HTTPS 的 RSA 加密。客户端使用公钥订阅推送，服务端使用私钥来发送通知。创建既可以在浏览器进行，也可以使用 Node 创建。当然，推荐在后端生成更安全。</p>\\n<p>前端生成代码参考链接：<a href=\\"https://github.com/acgotaku/sw-push/blob/master/src/utils/util.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">util.ts</a></p>\\n<p>后端使用<a href=\\"https://github.com/web-push-libs/web-push\\" target=\\"_blank\\" rel=\\"noreferrer\\">web-push</a>可以更方便的生成公钥和私钥。代码如下：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> generateVAPIDKeys</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> vapidKeys</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> webpush.</span><span style=\\"color:#6F42C1\\">generateVAPIDKeys</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    publicKey: vapidKeys.publicKey,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    privateKey: vapidKeys.privateKey</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><h3 id=\\"subscribing-with-the-public-key\\" tabindex=\\"-1\\">Subscribing with the public key <a class=\\"header-anchor\\" href=\\"#subscribing-with-the-public-key\\" aria-label=\\"Permalink to &quot;Subscribing with the public key&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>接下来我们需要订阅推送：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">navigator.serviceWorker.ready</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">registration</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> registration.pushManager.</span><span style=\\"color:#6F42C1\\">getSubscription</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">subscription</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (subscription </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> registration.pushManager.</span><span style=\\"color:#6F42C1\\">subscribe</span><span style=\\"color:#24292E\\">({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          userVisibleOnly: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          applicationServerKey: </span><span style=\\"color:#005CC5\\">this</span><span style=\\"color:#24292E\\">.vapidPublicKey</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> subscription;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  })</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">subscription</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.subJSON </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> subscription.</span><span style=\\"color:#6F42C1\\">toJSON</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br></div></div><p>我们使用公钥进行订阅，并且把订阅之后的内容打印出来，方便服务器使用。实际工程中需要发送给服务器进行保存。使用 Chrome 浏览器订阅的信息是这样的：</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"endpoint\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"https://fcm.googleapis.com/fcm/send/d3cMmjx0Eg8:APA91bF1i7wgLJRw-VgOh3Evn6RG1xqdOR6Y0CeTUm1xiD36BCHXaDoceVfilDYiifWdI_rWdU8IdJjqSxaCVscRp5zl9lon8u4mf9mha0fmSVKJzUOx5r5Jba2yiNmCFRxxKcTJm51S\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"expirationTime\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"keys\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"p256dh\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"BDtGmJB0Bkyum0WJw8NiiCn4U9ckX8UjhzXPUad2HM0yID0ced8zUHKr-Yhf6p2Z7IS0G07dGG7Tnl5jlwQVog4\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"auth\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"25JGSYqTKvj_nAeodHBHSQ\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>我们可以看到推送的网址是 Chrome 提供的服务，Firefox 浏览器下订阅的信息是这样的：</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"endpoint\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"https://updates.push.services.mozilla.com/wpush/v2/gAAAAABghCrItYXGJw0eCyp0Ae1lTxMXkb6Fxhg8tRck2cMoY4bZjvkV2j5t95FfrPftdieUgeaNthjmb0_XyoIVqWIy7cpy9lMjczHb5TYpC7sKnOw4IekwrtQbmBo6Vn54TZaUSrBIb40PEy2KXF5QlyOj2QxlTz6d6NPB6mMvJxuYNSg-5xs\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"keys\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"auth\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"MCeQnXlaz4A-CBuALNPbcQ\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"p256dh\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"BL4am0lzx005spT_UBbMagfWb93Cfgh8XtkCtP7y697dODFnO0wCVVI783BsiHePRTl-mrpoHolJ0gKTYR1T4SQ\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>从 <code>endpoint</code> 我们可以看出推送服务本身是浏览器提供的，如果无法访问这个网址，自然就无法使用推送服务。</p>\\n<h3 id=\\"server-push\\" tabindex=\\"-1\\">Server push <a class=\\"header-anchor\\" href=\\"#server-push\\" aria-label=\\"Permalink to &quot;Server push&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>接下来，我们让服务端发送一个消息试试：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> webpush</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> require</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'web-push'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> vapidPublicKey</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'public key'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> vapidPrivateKey</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'private key'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">// PushSubscriptionJSON Info</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> pushSubscription</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  endpoint: </span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  expirationTime: </span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  keys: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    p256dh: </span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    auth: </span><span style=\\"color:#032F62\\">''</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> payload</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'hello world!'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> options</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  vapidDetails: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    subject: </span><span style=\\"color:#032F62\\">'mailto:example@web-push-node.org'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    publicKey: vapidPublicKey,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    privateKey: vapidPrivateKey</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  TTL: </span><span style=\\"color:#005CC5\\">60</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">webpush</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">sendNotification</span><span style=\\"color:#24292E\\">(pushSubscription, payload, options)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">result</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'success!'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(result);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  })</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">catch</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">err</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'fail!'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">error</span><span style=\\"color:#24292E\\">(err);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br></div></div><p>在上述代码中填入相应的认证信息，就可以使用了。浏览器的推送功能并不需要把相应的网站打开，只要浏览器是打开的就可以收到推送。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>浏览器的推送功能非常方便，但是首先需要用户授权通知权限才能使用，其次是浏览器提供的推送服务，可能在中国无法正常使用。所以现在这个功能还没有大规模的应用。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developers.google.com/web/ilt/pwa/introduction-to-push-notifications\\" target=\\"_blank\\" rel=\\"noreferrer\\">Introduction to Push Notifications</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/codelabs/push-notifications\\" target=\\"_blank\\" rel=\\"noreferrer\\">Adding Push Notifications to a Web App</a></p>\\n<p><a href=\\"https://github.com/acgotaku/sw-push\\" target=\\"_blank\\" rel=\\"noreferrer\\">Service Worker Push Notifications Demo</a></p>\\n"}]},"relativePath":"page/11/index.md","filePath":"page/[page].md"}`),e={name:"page/11/index.md"};function p(l,o,r,c,t,i){return n(),a("div")}const u=s(e,[["render",p]]);export{d as __pageData,u as default};
